INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0008-000000000001', 'b0000001-0000-0000-0000-000000000008', 'b0000000-0000-0000-0000-000000000001', 1, 'el-clima-repaso-y-ampliacion', '{"es": "El Clima: Repaso y Ampliación", "en": "Weather: Review and Expansion"}'::jsonb, '{"es": "Repasa el vocabulario del clima que ya conoces y aprende palabras nuevas como snowy, stormy y mild.", "en": "Review the weather vocabulary you already know and learn new words like snowy, stormy, and mild."}'::jsonb, 'vocabulary', 20, 12, '{"intro": "Ya conoces palabras del clima como sunny, cloudy, rainy, windy, hot, cold, warm y foggy. En esta lección las vas a practicar y vas a aprender tres palabras nuevas: snowy, stormy y mild.", "sections": [{"type": "table", "title": "VOCABULARIO DEL CLIMA (REPASO)", "headers": ["Inglés", "Español"], "rows": [["sunny", "soleado"], ["cloudy", "nublado"], ["rainy", "lluvioso"], ["windy", "ventoso"], ["hot", "caluroso"], ["cold", "frío"], ["warm", "cálido"], ["foggy", "neblinoso"]]}, {"type": "table", "title": "VOCABULARIO NUEVO", "headers": ["Inglés", "Español"], "rows": [["snowy", "nevado"], ["stormy", "tormentoso"], ["mild", "templado / suave"]]}, {"type": "explanation", "title": "IT''S + ADJETIVO Y PREGUNTAS SOBRE EL CLIMA", "text": "Para hablar del clima usamos la estructura ''It''s + adjetivo'': ''It''s sunny'', ''It''s cold'', ''It''s stormy''. Para preguntar cómo está el clima decimos ''What''s the weather like today?'' (¿Cómo está el clima hoy?) y respondemos con ''It''s + adjetivo''."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "What''s the weather like today?", "es": "¿Cómo está el clima hoy?"}, {"en": "It''s sunny and warm.", "es": "Está soleado y cálido."}, {"en": "It''s snowy in the mountains.", "es": "Está nevado en las montañas."}, {"en": "It''s stormy, so I stay inside.", "es": "Está tormentoso, así que me quedo dentro."}, {"en": "It''s mild today, not too hot and not too cold.", "es": "Hoy hace un clima templado, ni muy caluroso ni muy frío."}]}, {"type": "note", "variant": "tip", "text": "''Mild'' se usa para describir un clima agradable, ni frío ni caluroso — muy común quando hablamos del clima en otoño o primavera."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0001-0008-0001-000000000001', 'b0000002-0000-0000-0008-000000000001', 1, 'flashcard', '{"text": "snowy"}'::jsonb, '{"text": "nevado", "phonetic": "/ˈsnoʊi/"}'::jsonb, NULL, NULL, '{"vocab:weather"}'),
('b0000003-0001-0008-0002-000000000001', 'b0000002-0000-0000-0008-000000000001', 2, 'flashcard', '{"text": "stormy"}'::jsonb, '{"text": "tormentoso", "phonetic": "/ˈstɔːrmi/"}'::jsonb, NULL, NULL, '{"vocab:weather"}'),
('b0000003-0001-0008-0003-000000000001', 'b0000002-0000-0000-0008-000000000001', 3, 'flashcard', '{"text": "mild"}'::jsonb, '{"text": "templado", "phonetic": "/maɪld/"}'::jsonb, NULL, NULL, '{"vocab:weather"}'),
('b0000003-0001-0008-0004-000000000001', 'b0000002-0000-0000-0008-000000000001', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "sunny", "es": "soleado"}, {"en": "cloudy", "es": "nublado"}, {"en": "windy", "es": "ventoso"}, {"en": "foggy", "es": "neblinoso"}]}'::jsonb, NULL, NULL, '{"vocab:weather"}'),
('b0000003-0001-0008-0005-000000000001', 'b0000002-0000-0000-0008-000000000001', 5, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "snowy", "es": "nevado"}, {"en": "stormy", "es": "tormentoso"}, {"en": "mild", "es": "templado"}, {"en": "rainy", "es": "lluvioso"}]}'::jsonb, NULL, NULL, '{"vocab:weather"}'),
('b0000003-0001-0008-0006-000000000001', 'b0000002-0000-0000-0008-000000000001', 6, 'multiple_choice', '{"text": "What''s the weather like today?"}'::jsonb, '{"text": "It''s sunny."}'::jsonb, '["It''s a sunny.", "It sunny.", "Is sunny."]'::jsonb, '{"es": "Usamos ''It''s + adjetivo'' para describir el clima, sin artículo antes del adjetivo."}'::jsonb, '{"vocab:weather"}'),
('b0000003-0001-0008-0007-000000000001', 'b0000002-0000-0000-0008-000000000001', 7, 'fill_blank', '{"text": "It''s very ___ today. I can see snow on the mountains."}'::jsonb, '{"text": "snowy", "accepted": ["snowy"]}'::jsonb, NULL, '{"es": "''Snowy'' describe un clima con nieve."}'::jsonb, '{"vocab:weather"}'),
('b0000003-0001-0008-0008-000000000001', 'b0000002-0000-0000-0008-000000000001', 8, 'translation', '{"text": "Hoy el clima está templado, ni frío ni caluroso."}'::jsonb, '{"text": "Today the weather is mild, not cold and not hot.", "accepted": ["Today the weather is mild, not cold and not hot.", "Today the weather''s mild, not cold and not hot."]}'::jsonb, NULL, NULL, '{"vocab:weather"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0008-000000000002', 'b0000001-0000-0000-0000-000000000008', 'b0000000-0000-0000-0000-000000000001', 2, 'actividades-segun-el-clima', '{"es": "Actividades Según el Clima", "en": "Activities Depending on the Weather"}'::jsonb, '{"es": "Aprende actividades relacionadas con el clima y combínalas usando la estructura when it''s + clima.", "en": "Learn activities related to the weather and combine them using the structure when it''s + weather."}'::jsonb, 'vocabulary', 22, 13, '{"intro": "El clima influye en lo que hacemos. En esta lección vas a aprender vocabulario de actividades y a combinarlo con el clima usando la estructura ''When it''s + clima, people + actividad''.", "sections": [{"type": "table", "title": "ACTIVIDADES SEGÚN EL CLIMA", "headers": ["Inglés", "Español"], "rows": [["go to the beach", "ir a la playa"], ["stay home", "quedarse en casa"], ["wear a coat", "llevar un abrigo"], ["use an umbrella", "usar un paraguas"], ["go skiing", "ir a esquiar"], ["have a picnic", "hacer un picnic"], ["go swimming", "ir a nadar"]]}, {"type": "explanation", "title": "WHEN IT''S + CLIMA, ... ", "text": "Usamos ''when'' (cuando) para conectar el clima con una actividad en presente simple: ''When it''s sunny, we go to the beach.'' La estructura es: When it''s + adjetivo, + sujeto + verbo en presente simple."}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "When it''s sunny, we go to the beach.", "es": "Cuando está soleado, vamos a la playa."}, {"en": "When it''s cold, people wear a coat.", "es": "Cuando hace frío, la gente lleva un abrigo."}, {"en": "When it''s rainy, I use an umbrella.", "es": "Cuando está lluvioso, uso un paraguas."}, {"en": "When it''s snowy, we go skiing.", "es": "Cuando está nevado, vamos a esquiar."}, {"en": "When it''s warm, they have a picnic in the park.", "es": "Cuando hace calor moderado, hacen un picnic en el parque."}]}, {"type": "note", "variant": "info", "text": "También podemos usar ''when'' al final de la oración: ''We go to the beach when it''s sunny.'' El significado es el mismo."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0002-0008-0001-000000000001', 'b0000002-0000-0000-0008-000000000002', 1, 'flashcard', '{"text": "go skiing", "subtext": "activity"}'::jsonb, '{"text": "ir a esquiar", "phonetic": "/ɡoʊ ˈskiːɪŋ/"}'::jsonb, NULL, NULL, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0002-000000000001', 'b0000002-0000-0000-0008-000000000002', 2, 'flashcard', '{"text": "have a picnic", "subtext": "activity"}'::jsonb, '{"text": "hacer un picnic", "phonetic": "/hæv ə ˈpɪknɪk/"}'::jsonb, NULL, NULL, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0003-000000000001', 'b0000002-0000-0000-0008-000000000002', 3, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "go to the beach", "es": "ir a la playa"}, {"en": "stay home", "es": "quedarse en casa"}, {"en": "wear a coat", "es": "llevar un abrigo"}, {"en": "use an umbrella", "es": "usar un paraguas"}]}'::jsonb, NULL, NULL, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0004-000000000001', 'b0000002-0000-0000-0008-000000000002', 4, 'word_match', '{"text": "Match each word with its translation"}'::jsonb, '{"pairs": [{"en": "go skiing", "es": "ir a esquiar"}, {"en": "have a picnic", "es": "hacer un picnic"}, {"en": "go swimming", "es": "ir a nadar"}, {"en": "stay home", "es": "quedarse en casa"}]}'::jsonb, NULL, NULL, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0005-000000000001', 'b0000002-0000-0000-0008-000000000002', 5, 'multiple_choice', '{"text": "When it''s rainy, what do people usually do?"}'::jsonb, '{"text": "They use an umbrella."}'::jsonb, '["They go to the beach.", "They go swimming.", "They have a picnic."]'::jsonb, '{"es": "Cuando llueve, la gente usa un paraguas (umbrella) para no mojarse."}'::jsonb, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0006-000000000001', 'b0000002-0000-0000-0008-000000000002', 6, 'fill_blank', '{"text": "When it''s snowy, we go ___."}'::jsonb, '{"text": "skiing", "accepted": ["skiing"]}'::jsonb, NULL, '{"es": "''Go skiing'' significa ir a esquiar, una actividad típica cuando nieva."}'::jsonb, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0007-000000000001', 'b0000002-0000-0000-0008-000000000002', 7, 'fill_blank', '{"text": "When it''s sunny and warm, families ___ in the park."}'::jsonb, '{"text": "have a picnic", "accepted": ["have a picnic"]}'::jsonb, NULL, NULL, '{"vocab:weather_activities"}'),
('b0000003-0002-0008-0008-000000000001', 'b0000002-0000-0000-0008-000000000002', 8, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "What''s the weather like today?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "Great, let''s go to the beach then!"}]}'::jsonb, '{"text": "It''s sunny and hot."}'::jsonb, '["It''s stormy and windy.", "It''s snowy and cold.", "It''s cloudy and rainy."]'::jsonb, NULL, '{"vocab:weather_activities","vocab:weather"}');
INSERT INTO lessons (id, module_id, unit_id, order_index, slug, title, description, lesson_type, xp_reward, estimated_minutes, theory_content, is_published) VALUES
('b0000002-0000-0000-0008-000000000003', 'b0000001-0000-0000-0000-000000000008', 'b0000000-0000-0000-0000-000000000001', 3, 'el-clima-en-el-pasado', '{"es": "El Clima en el Pasado", "en": "Weather in the Past"}'::jsonb, '{"es": "Combina was/were y el pasado simple con el vocabulario del clima para describir qué tiempo hacía y qué hizo la gente.", "en": "Combine was/were and past simple with weather vocabulary to describe what the weather was like and what people did."}'::jsonb, 'mixed', 24, 14, '{"intro": "Ya sabes usar ''was/were'' y el pasado simple. Ahora vas a combinarlos con el vocabulario del clima para contar cómo era el clima en el pasado y qué hicieron las personas.", "sections": [{"type": "table", "title": "WAS / WERE + CLIMA", "headers": ["Sujeto", "Forma", "Ejemplo"], "rows": [["it", "was", "It was sunny yesterday."], ["the mornings", "were", "The mornings were cold last week."]]}, {"type": "explanation", "title": "COMBINANDO CLIMA Y ACCIONES PASADAS", "text": "Podemos describir el clima en el pasado con ''was/were'' y unirlo a una acción con ''so'' (así que) para mostrar causa y efecto: ''It was sunny, so we went to the park.'' También podemos usar el pasado simple del verbo estar lloviendo: ''It rained all day, so we stayed home.''"}, {"type": "examples", "title": "EJEMPLOS", "items": [{"en": "It was sunny, so we went to the park.", "es": "Estaba soleado, así que fuimos al parque."}, {"en": "It rained all day, so we stayed home and watched TV.", "es": "Llovió todo el día, así que nos quedamos en casa y vimos la tele."}, {"en": "It was very cold, so I wore a coat.", "es": "Hacía mucho frío, así que llevé un abrigo."}, {"en": "The weather was stormy, so they didn''t go swimming.", "es": "El clima estaba tormentoso, así que no fueron a nadar."}, {"en": "It was snowy, so we went skiing.", "es": "Estaba nevado, así que fuimos a esquiar."}]}, {"type": "note", "variant": "warning", "text": "No uses ''will'' o ''going to'' para hablar de predicciones del clima en esta lección — solo describimos el clima en pasado o presente, con acciones ya conocidas."}]}'::jsonb, true);
INSERT INTO exercises (id, lesson_id, order_index, exercise_type, prompt, correct_answer, distractors, explanation, tags) VALUES
('b0000003-0003-0008-0001-000000000001', 'b0000002-0000-0000-0008-000000000003', 1, 'multiple_choice', '{"text": "___ sunny yesterday, so we went to the park."}'::jsonb, '{"text": "It was"}'::jsonb, '["It were", "It is", "It did"]'::jsonb, '{"es": "Con ''it'' (singular) en pasado usamos ''was''."}'::jsonb, '{"grammar:past_weather"}'),
('b0000003-0003-0008-0002-000000000001', 'b0000002-0000-0000-0008-000000000003', 2, 'multiple_choice', '{"text": "The mornings ___ very cold last week."}'::jsonb, '{"text": "were"}'::jsonb, '["was", "is", "are"]'::jsonb, '{"es": "Con ''the mornings'' (plural) en pasado usamos ''were''."}'::jsonb, '{"grammar:past_weather"}'),
('b0000003-0003-0008-0003-000000000001', 'b0000002-0000-0000-0008-000000000003', 3, 'fill_blank', '{"text": "It ___ all day yesterday, so we stayed home."}'::jsonb, '{"text": "rained", "accepted": ["rained"]}'::jsonb, NULL, '{"es": "''Rained'' es el pasado simple regular de ''rain''."}'::jsonb, '{"grammar:past_simple","vocab:weather"}'),
('b0000003-0003-0008-0004-000000000001', 'b0000002-0000-0000-0008-000000000003', 4, 'fill_blank', '{"text": "It was snowy, so we ___ skiing."}'::jsonb, '{"text": "went", "accepted": ["went"]}'::jsonb, NULL, '{"es": "''Went'' es el pasado simple irregular de ''go''."}'::jsonb, '{"grammar:past_simple_irregular","vocab:weather_activities"}'),
('b0000003-0003-0008-0005-000000000001', 'b0000002-0000-0000-0008-000000000003', 5, 'fill_blank', '{"text": "The weather was stormy, so they ___ go swimming."}'::jsonb, '{"text": "didn''t", "accepted": ["didn''t", "did not"]}'::jsonb, NULL, '{"es": "Usamos ''didn''t + verbo base'' para el negativo del pasado simple."}'::jsonb, '{"grammar:past_simple","vocab:weather_activities"}'),
('b0000003-0003-0008-0006-000000000001', 'b0000002-0000-0000-0008-000000000003', 6, 'translation', '{"text": "Estaba soleado, así que fuimos a la playa."}'::jsonb, '{"text": "It was sunny, so we went to the beach.", "accepted": ["It was sunny, so we went to the beach."]}'::jsonb, NULL, NULL, '{"grammar:past_weather","vocab:weather_activities"}'),
('b0000003-0003-0008-0007-000000000001', 'b0000002-0000-0000-0008-000000000003', 7, 'translation', '{"text": "Llovió todo el día, así que nos quedamos en casa y vimos la tele."}'::jsonb, '{"text": "It rained all day, so we stayed home and watched TV.", "accepted": ["It rained all day, so we stayed home and watched TV."]}'::jsonb, NULL, NULL, '{"grammar:past_simple","vocab:weather_activities"}'),
('b0000003-0003-0008-0008-000000000001', 'b0000002-0000-0000-0008-000000000003', 8, 'dialogue_fill', '{"lines": [{"speaker": "A", "text": "What was the weather like yesterday?"}, {"speaker": "B", "text": "___"}, {"speaker": "A", "text": "That''s why you stayed home!"}]}'::jsonb, '{"text": "It was stormy, so I didn''t go out."}'::jsonb, '["It was sunny, so I went to the beach.", "It is mild today.", "It will be cold tomorrow."]'::jsonb, NULL, '{"grammar:past_weather","vocab:weather_activities"}');
